export type IconName = keyof typeof FILLED | keyof typeof STROKED;

/** Decorative icon (aria-hidden) in `currentColor`; size it with `size-*`. */
export function Icon({ name, className }: { name: IconName; className?: string }) {
  const cls = cn("shrink-0", className);
  if (name in STROKED) {
    return (
      <svg aria-hidden viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" className={cls}>
        <path d={STROKED[name as keyof typeof STROKED]} />
      </svg>
    );
  }
  return <svg aria-hidden viewBox="0 0 14 14" fill="currentColor" className={cls}><path d={FILLED[name as keyof typeof FILLED]} /></svg>;
}
